import { useCallback, useEffect, useId, useState } from "react";
import {
  Checkbox,
  Input,
  Label,
  Radio,
  RadioGroup,
  mergeClasses,
} from "@fluentui/react-components";
import { ArrowLeft24Regular } from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import type { ThemeMode } from "../theme/fluentTheme";
import { HsButton } from "./primitives/Button";
import { HsPanel } from "./primitives/Panel";
import { HsSelect } from "./primitives/Select";
import { HsNumericField } from "./primitives/NumericField";
import {
  StatusBadge,
  type StatusTone,
} from "./primitives/StatusBadge";
import type { ExportPort } from "../export/port";
import type { DiagnosticsPort } from "../diagnostics/port";
import type { DiagnosticsInfo, ToolInfo } from "../diagnostics/types";
import {
  SETTINGS_CATEGORIES,
  playbackRateOptions,
  type AppSettings,
  type SettingsCategory,
} from "../settings/store";
import {
  clearRecordings,
  collectReferencedRecordingNames,
  deleteRecording,
  deleteSource,
  formatBytes,
  getRecordingsInfo,
  getSourcesInfo,
  listRecordings,
  listSources,
  openRecordingsDir,
  openSourcesDir,
  type RecordingFile,
  type RecordingsInfo,
} from "../capture/recordings";
import { HsDialog } from "./primitives/Dialog";
import { createImportPorts } from "../import/runtimePorts";
import { parseProjectFile } from "../import/controller";
import type { RecentProjectEntry } from "../import/types";

const CATEGORY_LABEL: Record<SettingsCategory, string> = {
  appearance: ja.settings.appearanceSection,
  playback: ja.settings.playbackSection,
  recordings: ja.settings.recordingsSection,
  transcription: ja.settings.transcriptionSection,
  score: ja.settings.scoreSection,
  export: ja.settings.exportSection,
  tools: ja.settings.toolsSection,
  advanced: ja.settings.advancedSection,
};

function toolBadge(info: ToolInfo | undefined): {
  tone: StatusTone;
  label: string;
} {
  const s = ja.dependencies;
  const status = info?.status ?? "checking";
  return status === "found"
    ? { tone: "success", label: s.statusFound }
    : status === "missing"
      ? { tone: "error", label: s.statusMissing }
      : status === "checking"
        ? { tone: "info", label: s.statusChecking }
        : { tone: "neutral", label: ja.diagnostics.unknown };
}

/**
 * Editable path field (tool locations, 既定の保存先). The draft commits on
 * blur/Enter so every keystroke does not re-probe tool status.
 */
function PathField({
  label,
  value,
  placeholder,
  onCommit,
  trailing,
}: {
  label: string;
  value: string;
  placeholder?: string;
  onCommit(value: string): void;
  trailing?: React.ReactNode;
}) {
  const id = useId();
  const [draft, setDraft] = useState(value);
  useEffect(() => setDraft(value), [value]);
  const commit = () => {
    if (draft !== value) onCommit(draft);
  };
  return (
    <div className="hs-settings__field">
      <Label id={id}>{label}</Label>
      <div className="hs-settings__path-row">
        <Input
          aria-labelledby={id}
          value={draft}
          placeholder={placeholder}
          onChange={(_, d) => setDraft(d.value)}
          onBlur={commit}
          onKeyDown={(ev) => {
            if (ev.key === "Enter") commit();
          }}
        />
        {trailing}
      </div>
    </div>
  );
}

/**
 * 設定 — auxiliary screen, not a work mode (GUI_UX_SPEC §18; issue UI-060).
 *
 * Left nav lists the categories (外観/再生/録音/採譜/楽譜/書き出し/ツール/
 * 詳細設定); only the selected panel renders, so advanced settings never
 * leak into the workspace. There is intentionally NO language setting —
 * the UI is Japanese-only by contract.
 *
 * Values persist to localStorage immediately (same precedent as the theme
 * switcher). Tool paths are user-editable; a non-empty path wins over
 * auto-detection in the diagnostics probe.
 */
export function SettingsView({
  themeMode,
  onThemeMode,
  onBack,
  settings,
  onSettingsChange,
  diagnosticsPort,
  exportPort,
  onOpenDiagnostics,
  onAnnounce,
  focusCategory,
  recentProjects = [],
}: {
  themeMode: ThemeMode;
  onThemeMode(m: ThemeMode): void;
  onBack(): void;
  settings: AppSettings;
  onSettingsChange(patch: Partial<AppSettings>): void;
  diagnosticsPort: DiagnosticsPort;
  exportPort: ExportPort;
  onOpenDiagnostics(): void;
  /** Status-bar announcements (role="status" is aria-live). */
  onAnnounce(message: string): void;
  /** Deep-link target (e.g. "export" from the MuseScore recovery action). */
  focusCategory?: SettingsCategory;
  /** #147: MRU projects — used to flag managed sources still referenced
   *  by a saved project before the user deletes them. */
  recentProjects?: readonly RecentProjectEntry[];
}) {
  const s = ja.settings;
  const [category, setCategory] = useState<SettingsCategory>(
    focusCategory ?? "appearance",
  );
  useEffect(() => {
    if (focusCategory) setCategory(focusCategory);
  }, [focusCategory]);

  // Tool status / paths for ツール + 詳細設定 — collected once, then again
  // whenever the user commits a different tool path (the override flips
  // the reported status to 検出済み).
  const [diag, setDiag] = useState<DiagnosticsInfo | null>(null);
  useEffect(() => {
    let cancelled = false;
    void diagnosticsPort
      .collect({
        museScorePath: settings.museScorePath,
        ffmpegPath: settings.ffmpegPath,
      })
      .then((info) => {
        if (!cancelled) setDiag(info);
      })
      .catch(() => undefined);
    return () => {
      cancelled = true;
    };
  }, [diagnosticsPort, settings.museScorePath, settings.ffmpegPath]);

  const pickExportDir = useCallback(async () => {
    try {
      const dir = await exportPort.chooseDestination(
        settings.defaultExportDir || undefined,
      );
      if (dir) onSettingsChange({ defaultExportDir: dir });
    } catch {
      /* picker unavailable (unsupported port) — the field stays editable */
    }
  }, [exportPort, settings.defaultExportDir, onSettingsChange]);

  const museBadge = toolBadge(diag?.tools.museScore);
  const ffmpegBadge = toolBadge(diag?.tools.ffmpeg);

  const openLogs = useCallback(async () => {
    const ok = await diagnosticsPort.openLogFolder();
    if (!ok) {
      // Honest feedback — the shell has no folder bridge yet.
      onAnnounce(ja.diagnostics.openLogsFailed);
    }
  }, [diagnosticsPort, onAnnounce]);

  // #78: 録音ファイル管理 — カテゴリを開いた時に情報を取り直す。
  const [recInfo, setRecInfo] = useState<RecordingsInfo | null>(null);
  const [recFiles, setRecFiles] = useState<RecordingFile[] | null>(null);
  const [clearConfirmOpen, setClearConfirmOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<string | null>(null);
  const refreshRecordings = useCallback(() => {
    void getRecordingsInfo().then(setRecInfo);
    void listRecordings().then(setRecFiles);
  }, []);
  useEffect(() => {
    if (category === "recordings") refreshRecordings();
  }, [category, refreshRecordings]);

  // #147: managed 音源(sources/) — プロジェクト保存時にコピーされた
  // 録音の永続領域。参照判定は最近のプロジェクト(MRU)で行い、
  // 読めない/履歴外のプロジェクトは fail-open(参照なし扱い)。
  const [srcInfo, setSrcInfo] = useState<RecordingsInfo | null>(null);
  const [srcFiles, setSrcFiles] = useState<RecordingFile[] | null>(null);
  const [srcReferenced, setSrcReferenced] = useState<ReadonlySet<string>>(
    new Set(),
  );
  const [srcDeleteTarget, setSrcDeleteTarget] = useState<string | null>(
    null,
  );
  const refreshSources = useCallback(() => {
    void getSourcesInfo().then((info) => {
      setSrcInfo(info);
      if (!info) {
        setSrcReferenced(new Set());
        return;
      }
      const ports = createImportPorts();
      void collectReferencedRecordingNames({
        readProjectBytes: ports.readProjectBytes,
        entries: recentProjects,
        dir: info.dir,
        sourcePathOf: async (blob) =>
          parseProjectFile(await blob.arrayBuffer(), "").sourcePath,
      }).then(setSrcReferenced);
    });
    void listSources().then(setSrcFiles);
  }, [recentProjects]);
  useEffect(() => {
    if (category === "recordings") refreshSources();
  }, [category, refreshSources]);

  const section = (() => {
    switch (category) {
      case "appearance":
        return (
          <>
            <Label id="hs-theme-label">{s.themeLabel}</Label>
            <RadioGroup
              aria-labelledby="hs-theme-label"
              value={themeMode}
              onChange={(_, data) => onThemeMode(data.value as ThemeMode)}
            >
              <Radio value="system" label={s.themeSystem} />
              <Radio value="light" label={s.themeLight} />
              <Radio value="dark" label={s.themeDark} />
            </RadioGroup>
          </>
        );

      case "playback":
        return (
          <>
            <HsSelect
              label={s.defaultRate}
              value={String(settings.playbackRate)}
              options={playbackRateOptions().map((r) => ({
                value: String(r),
                label: `${r}×`,
              }))}
              onChange={(v) =>
                onSettingsChange({ playbackRate: Number(v) })
              }
            />
            <HsNumericField
              label={s.skipSeconds}
              value={settings.skipSeconds}
              min={1}
              max={60}
              step={1}
              unit={s.secondsUnit}
              onChange={(v) =>
                v != null && onSettingsChange({ skipSeconds: v })
              }
            />
            <Checkbox
              checked={settings.followPlayback}
              onChange={(_, d) =>
                onSettingsChange({ followPlayback: d.checked === true })
              }
              label={s.followPlayback}
            />
          </>
        );

      case "recordings":
        return (
          <>
            <div className="hs-settings__field">
              <Label>{s.recordingsFolder}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {recInfo?.dir ?? ja.diagnostics.notConnected}
                </p>
                <HsButton
                  size="small"
                  disabled={!recInfo}
                  onClick={() => {
                    void openRecordingsDir().then((ok) => {
                      if (!ok) onAnnounce(s.recordingsUnavailable);
                    });
                  }}
                >
                  {s.recordingsOpen}
                </HsButton>
              </div>
            </div>
            <div className="hs-settings__field">
              <Label>{s.recordingsSection}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {recInfo
                    ? recInfo.fileCount > 0
                      ? `${s.recordingsCount(recInfo.fileCount)} — ${formatBytes(recInfo.totalBytes)}`
                      : s.recordingsEmpty
                    : s.recordingsUnavailable}
                </p>
                <HsButton
                  size="small"
                  disabled={!recInfo || recInfo.fileCount === 0}
                  onClick={() => setClearConfirmOpen(true)}
                >
                  {s.recordingsClear}
                </HsButton>
              </div>
            </div>
            {/* #78: 個別削除 — 全削除だけだと「残したい録音」も消える。 */}
            {recFiles && recFiles.length > 0 && (
              <div className="hs-settings__field">
                <ul className="hs-settings__recording-list">
                  {recFiles.map((f) => (
                    <li key={f.name} className="hs-settings__recording-item">
                      <span className="hs-settings__recording-name">
                        {f.name}
                      </span>
                      <span className="hs-settings__recording-size">
                        {formatBytes(f.bytes)}
                      </span>
                      <HsButton
                        size="small"
                        variant="secondary"
                        onClick={() => setDeleteTarget(f.name)}
                      >
                        {s.recordingsDelete}
                      </HsButton>
                    </li>
                  ))}
                </ul>
              </div>
            )}
            {/* #87: 保持日数ポリシー — 起動時に古いWAVを自動削除。 */}
            <HsSelect
              label={s.recordingsRetention}
              value={String(settings.recordingsRetentionDays)}
              options={[0, 7, 30, 90].map((d) => ({
                value: String(d),
                label:
                  d === 0
                    ? s.recordingsRetentionNever
                    : s.recordingsRetentionDays(d),
              }))}
              onChange={(v) =>
                onSettingsChange({ recordingsRetentionDays: Number(v) })
              }
            />
            {/* #147: プロジェクト保存時にコピーされた managed 音源。
                保持ポリシーは掛からないので容量はユーザー管理 — 件数・
                使用量・個別削除をここに集約する。 */}
            <div className="hs-settings__field">
              <Label>{s.sourcesSection}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {srcInfo
                    ? srcInfo.fileCount > 0
                      ? s.sourcesCount(srcInfo.fileCount) +
                        " — " +
                        formatBytes(srcInfo.totalBytes)
                      : s.sourcesEmpty
                    : s.recordingsUnavailable}
                </p>
                <HsButton
                  size="small"
                  disabled={!srcInfo}
                  onClick={() => {
                    void openSourcesDir().then((ok) => {
                      if (!ok) onAnnounce(s.recordingsUnavailable);
                    });
                  }}
                >
                  {s.recordingsOpen}
                </HsButton>
              </div>
            </div>
            {srcFiles && srcFiles.length > 0 && (
              <div className="hs-settings__field">
                <ul className="hs-settings__recording-list">
                  {srcFiles.map((f) => (
                    <li key={f.name} className="hs-settings__recording-item">
                      <span className="hs-settings__recording-name">
                        {f.name}
                        {srcReferenced.has(f.name) ? (
                          <span className="hs-settings__recording-ref">
                            {s.sourcesReferenced}
                          </span>
                        ) : null}
                      </span>
                      <span className="hs-settings__recording-size">
                        {formatBytes(f.bytes)}
                      </span>
                      <HsButton
                        size="small"
                        variant="secondary"
                        onClick={() => setSrcDeleteTarget(f.name)}
                      >
                        {s.recordingsDelete}
                      </HsButton>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </>
        );

      case "transcription":
        return (
          <>
            <HsSelect
              label={s.tempo}
              value={settings.tempoMode}
              options={[
                { value: "auto", label: s.tempoAuto },
                { value: "manual", label: s.tempoManual },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  tempoMode: v === "manual" ? "manual" : "auto",
                })
              }
            />
            <HsNumericField
              label={s.bpm}
              value={settings.bpm}
              min={30}
              max={300}
              step={1}
              disabled={settings.tempoMode === "auto"}
              onChange={(v) => v != null && onSettingsChange({ bpm: v })}
            />
            <HsSelect
              label={s.meter}
              value={settings.meter}
              options={[
                { value: "auto", label: s.tempoAuto },
                { value: "4/4", label: "4/4" },
                { value: "3/4", label: "3/4" },
                { value: "6/8", label: "6/8" },
                { value: "2/4", label: "2/4" },
                { value: "5/4", label: "5/4" },
                { value: "7/8", label: "7/8" },
                { value: "9/8", label: "9/8" },
                { value: "12/8", label: "12/8" },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  meter: v as AppSettings["meter"],
                })
              }
            />
            <HsSelect
              label={s.minDuration}
              value={settings.minDuration}
              options={[
                { value: "eighth", label: s.minDurationEighth },
                { value: "sixteenth", label: s.minDurationSixteenth },
                {
                  value: "thirtySecond",
                  label: s.minDurationThirtySecond,
                },
              ]}
              onChange={(v) =>
                onSettingsChange({
                  minDuration: v as AppSettings["minDuration"],
                })
              }
            />
            <Checkbox
              checked={settings.triplets}
              onChange={(_, d) =>
                onSettingsChange({ triplets: d.checked === true })
              }
              label={s.tripletsAllow}
            />
          </>
        );

      case "score":
        return (
          <HsSelect
            label={s.initialView}
            value={settings.scoreInitialView}
            options={[
              { value: "continuous", label: s.viewContinuous },
              { value: "page", label: s.viewPage },
            ]}
            onChange={(v) =>
              onSettingsChange({
                scoreInitialView: v === "page" ? "page" : "continuous",
              })
            }
          />
        );

      case "export":
        return (
          <>
            <PathField
              label={s.defaultFolder}
              value={settings.defaultExportDir}
              placeholder={s.folderPlaceholder}
              onCommit={(v) => onSettingsChange({ defaultExportDir: v })}
              trailing={
                <HsButton size="small" onClick={() => void pickExportDir()}>
                  {ja.common.browse}
                </HsButton>
              }
            />
            <PathField
              label={s.musescorePath}
              value={settings.museScorePath}
              placeholder={s.pathPlaceholder}
              onCommit={(v) => onSettingsChange({ museScorePath: v })}
              trailing={
                <StatusBadge tone={museBadge.tone} label={museBadge.label} />
              }
            />
          </>
        );

      case "tools":
        return (
          <>
            <div className="hs-settings__tool">
              <div className="hs-settings__tool-head">
                <span className="hs-settings__tool-name">FFmpeg</span>
                <StatusBadge
                  tone={ffmpegBadge.tone}
                  label={ffmpegBadge.label}
                />
              </div>
              <p className="hs-settings__note">
                {ja.dependencies.ffmpeg.purpose}
              </p>
              <PathField
                label={s.ffmpegPath}
                value={settings.ffmpegPath}
                placeholder={s.pathPlaceholder}
                onCommit={(v) => onSettingsChange({ ffmpegPath: v })}
              />
            </div>
            <div className="hs-settings__tool">
              <div className="hs-settings__tool-head">
                <span className="hs-settings__tool-name">MuseScore</span>
                <StatusBadge
                  tone={museBadge.tone}
                  label={museBadge.label}
                />
              </div>
              <p className="hs-settings__note">
                {ja.dependencies.musescore.purpose}
              </p>
              <PathField
                label={s.musescorePath}
                value={settings.museScorePath}
                placeholder={s.pathPlaceholder}
                onCommit={(v) => onSettingsChange({ museScorePath: v })}
              />
            </div>
            <div className="hs-settings__field">
              <Label>{s.modelInfo}</Label>
              <p className="hs-settings__value">
                {diag?.backend ?? ja.diagnostics.notConnected}
              </p>
            </div>
          </>
        );

      case "advanced":
        return (
          <>
            <HsSelect
              label={s.backendLabel}
              value={settings.backend}
              options={[
                { value: "auto", label: s.tempoAuto },
                { value: "basicPitch", label: "Basic Pitch" },
                { value: "pyin", label: "pYIN（単音）" },
              ]}
              hint={s.backendHint}
              onChange={(v) =>
                onSettingsChange({
                  backend:
                    v === "basicPitch" || v === "pyin" ? v : "auto",
                })
              }
            />
            <div className="hs-settings__field">
              <Label>{s.cache}</Label>
              <p className="hs-settings__value">
                {diag?.paths.cache ?? ja.diagnostics.notConnected}
              </p>
            </div>
            <div className="hs-settings__field">
              <Label>{s.logs}</Label>
              <div className="hs-settings__path-row">
                <p className="hs-settings__value">
                  {diag?.paths.logs ?? ja.diagnostics.notConnected}
                </p>
                <HsButton
                  size="small"
                  onClick={() => void openLogs()}
                >
                  {s.openLogs}
                </HsButton>
              </div>
            </div>
            <div className="hs-settings__field">
              <HsButton onClick={onOpenDiagnostics}>
                {s.openDiagnostics}
              </HsButton>
            </div>
          </>
        );
    }
  })();

  return (
    <div
      className="hs-settings"
      role="region"
      aria-label={s.regionLabel}
      data-hs-focus-zone="settings"
      tabIndex={-1}
    >
      <HsButton
        variant="subtle"
        icon={<ArrowLeft24Regular />}
        onClick={onBack}
      >
        {s.back}
      </HsButton>
      <h1 className="hs-settings__title">{s.title}</h1>

      <div className="hs-settings__layout">
        <nav className="hs-settings__nav" aria-label={s.navLabel}>
          {SETTINGS_CATEGORIES.map((c) => (
            <button
              key={c}
              type="button"
              className={mergeClasses(
                "hs-settings__nav-item",
                c === category && "hs-settings__nav-item--active",
              )}
              aria-current={c === category ? "true" : undefined}
              onClick={() => setCategory(c)}
            >
              {CATEGORY_LABEL[c]}
            </button>
          ))}
        </nav>

        <div className="hs-settings__content">
          <HsPanel
            key={category}
            title={CATEGORY_LABEL[category]}
            titleLevel={2}
            className="hs-settings__section"
          >
            <div className="hs-settings__fields">{section}</div>
          </HsPanel>
        </div>
      </div>

      {/* #78: 録音の全削除は破壊的操作 — alert 確認を挟む。 */}
      <HsDialog
        open={clearConfirmOpen}
        modalType="alert"
        title={s.recordingsClearConfirmTitle}
        onOpenChange={(open) => {
          if (!open) setClearConfirmOpen(false);
        }}
        actions={
          <>
            <HsButton
              variant="danger"
              onClick={() => {
                setClearConfirmOpen(false);
                void clearRecordings().then((freed) => {
                  if (freed !== null) {
                    onAnnounce(
                      `${s.recordingsCleared} (${formatBytes(freed)})`,
                    );
                  }
                  refreshRecordings();
                });
              }}
            >
              {s.recordingsClearConfirm}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => setClearConfirmOpen(false)}
            >
              {ja.capture.replaceCancel}
            </HsButton>
          </>
        }
      >
        <p style={{ margin: 0 }}>{s.recordingsClearConfirmBody}</p>
      </HsDialog>

      {/* #78: 個別削除も破壊的 — ファイル名を明示して確認する。 */}
      <HsDialog
        open={deleteTarget !== null}
        modalType="alert"
        title={s.recordingsDeleteConfirmTitle}
        onOpenChange={(open) => {
          if (!open) setDeleteTarget(null);
        }}
        actions={
          <>
            <HsButton
              variant="danger"
              onClick={() => {
                const name = deleteTarget;
                setDeleteTarget(null);
                if (name) {
                  void deleteRecording(name).then((ok) => {
                    if (ok) onAnnounce(s.recordingsDeleted);
                    refreshRecordings();
                  });
                }
              }}
            >
              {s.recordingsDelete}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => setDeleteTarget(null)}
            >
              {ja.capture.replaceCancel}
            </HsButton>
          </>
        }
      >
        <p style={{ margin: 0 }}>
          {deleteTarget ? s.recordingsDeleteConfirmBody(deleteTarget) : ""}
        </p>
      </HsDialog>

      {/* #147: managed 音源の削除 — 保存済みプロジェクトが参照する
          ファイルは警告文を変えて知らせる(削除自体は許可: 参照は別
          プロジェクトの所有物で、判断はユーザー)。 */}
      <HsDialog
        open={srcDeleteTarget !== null}
        modalType="alert"
        title={s.sourcesDeleteConfirmTitle}
        onOpenChange={(open) => {
          if (!open) setSrcDeleteTarget(null);
        }}
        actions={
          <>
            <HsButton
              variant="danger"
              onClick={() => {
                const name = srcDeleteTarget;
                setSrcDeleteTarget(null);
                if (name) {
                  void deleteSource(name).then((ok) => {
                    if (ok) onAnnounce(s.sourcesDeleted);
                    refreshSources();
                  });
                }
              }}
            >
              {s.recordingsDelete}
            </HsButton>
            <HsButton
              variant="secondary"
              onClick={() => setSrcDeleteTarget(null)}
            >
              {ja.capture.replaceCancel}
            </HsButton>
          </>
        }
      >
        <p style={{ margin: 0 }}>
          {srcDeleteTarget
            ? srcReferenced.has(srcDeleteTarget)
              ? s.sourcesDeleteConfirmBodyReferenced(srcDeleteTarget)
              : s.sourcesDeleteConfirmBody(srcDeleteTarget)
            : ""}
        </p>
      </HsDialog>
    </div>
  );
}

/**
 * Settings persistence (UI-060; GUI_UX_SPEC §18/§26).
 *
 * User-facing settings live in one localStorage record (mirroring the
 * existing `hornscribe.theme` / layout persistence — best-effort, never
 * crashes when storage is unavailable or holds stale/foreign data).
 * Only known keys are merged back and every value is re-validated, so a
 * corrupt or newer-version blob degrades to defaults field by field.
 *
 * NO language setting exists — the UI is Japanese-only by contract.
 */

import { useCallback, useMemo, useState } from "react";

const STORAGE_KEY = "hornscribe.settings";

/** The §18 categories in display order (録音 sits between 再生 and 採譜). */
export const SETTINGS_CATEGORIES = [
  "appearance",
  "playback",
  "recordings",
  "transcription",
  "score",
  "export",
  "tools",
  "advanced",
] as const;

export type SettingsCategory = (typeof SETTINGS_CATEGORIES)[number];

export type TempoMode = "auto" | "manual";
export type MeterSetting =
  | "auto"
  | "4/4"
  | "3/4"
  | "6/8"
  | "2/4"
  | "5/4"
  | "7/8"
  | "9/8"
  | "12/8";
export type MinDurationSetting = "eighth" | "sixteenth" | "thirtySecond";
export type ScoreViewMode = "continuous" | "page";
export type BackendSetting = "auto" | "basicPitch" | "pyin";

export interface AppSettings {
  /** 再生 → 標準再生速度 (0.5–2.0). */
  readonly playbackRate: number;
  /** 再生 → 戻る/進む秒数. */
  readonly skipSeconds: number;
  /** 再生 → 再生位置を追従. */
  readonly followPlayback: boolean;
  /** 採譜 → テンポ auto/manual + BPM value. */
  readonly tempoMode: TempoMode;
  readonly bpm: number;
  /** 採譜 → 拍子. */
  readonly meter: MeterSetting;
  /** 採譜 → 最小音価. */
  readonly minDuration: MinDurationSetting;
  /** 採譜 → 三連符を使う. */
  readonly triplets: boolean;
  /** 楽譜 → 初期表示. */
  readonly scoreInitialView: ScoreViewMode;
  /** 書き出し → 既定の保存先 ("" = choose at export time). */
  readonly defaultExportDir: string;
  /** 書き出し → MuseScoreの場所 ("" = auto-detect). */
  readonly museScorePath: string;
  /** ツール → FFmpegの場所 ("" = auto-detect). */
  readonly ffmpegPath: string;
  /** 詳細設定 → 採譜エンジン. */
  readonly backend: BackendSetting;
  /** 録音 → 自動削除の保持日数 (0 = 削除しない). */
  readonly recordingsRetentionDays: number;
}

export const DEFAULT_SETTINGS: AppSettings = {
  playbackRate: 1,
  skipSeconds: 5,
  followPlayback: true,
  tempoMode: "auto",
  bpm: 120,
  meter: "auto",
  minDuration: "sixteenth",
  triplets: true,
  scoreInitialView: "continuous",
  defaultExportDir: "",
  museScorePath: "",
  ffmpegPath: "",
  backend: "auto",
  recordingsRetentionDays: 0,
};

const RATES = [0.5, 0.75, 1, 1.25, 1.5, 2];
const METERS: readonly MeterSetting[] = [
  "auto",
  "4/4",
  "3/4",
  "6/8",
  "2/4",
  "5/4",
  "7/8",
  "9/8",
  "12/8",
];
const MIN_DURATIONS: readonly MinDurationSetting[] = [
  "eighth",
  "sixteenth",
  "thirtySecond",
];
const VIEWS: readonly ScoreViewMode[] = ["continuous", "page"];
const BACKENDS: readonly BackendSetting[] = ["auto", "basicPitch", "pyin"];

function num(v: unknown, min: number, max: number): number | null {
  return typeof v === "number" && Number.isFinite(v) && v >= min && v <= max
    ? v
    : null;
}
function str(v: unknown): string | null {
  return typeof v === "string" ? v : null;
}
function bool(v: unknown): boolean | null {
  return typeof v === "boolean" ? v : null;
}
function oneOf<T extends string>(v: unknown, list: readonly T[]): T | null {
  return typeof v === "string" && (list as readonly string[]).includes(v)
    ? (v as T)
    : null;
}

/** Parse + validate the stored blob; unknown/invalid fields get defaults. */
export function parseSettings(raw: string | null): AppSettings {
  if (!raw) return DEFAULT_SETTINGS;
  let o: Record<string, unknown>;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return DEFAULT_SETTINGS;
    o = parsed as Record<string, unknown>;
  } catch {
    return DEFAULT_SETTINGS;
  }
  const d = DEFAULT_SETTINGS;
  return {
    playbackRate: num(o.playbackRate, 0.25, 4) ?? d.playbackRate,
    skipSeconds: num(o.skipSeconds, 1, 60) ?? d.skipSeconds,
    followPlayback: bool(o.followPlayback) ?? d.followPlayback,
    tempoMode: oneOf(o.tempoMode, ["auto", "manual"]) ?? d.tempoMode,
    bpm: num(o.bpm, 30, 300) ?? d.bpm,
    meter: oneOf(o.meter, METERS) ?? d.meter,
    minDuration: oneOf(o.minDuration, MIN_DURATIONS) ?? d.minDuration,
    triplets: bool(o.triplets) ?? d.triplets,
    scoreInitialView: oneOf(o.scoreInitialView, VIEWS) ?? d.scoreInitialView,
    defaultExportDir: str(o.defaultExportDir) ?? d.defaultExportDir,
    museScorePath: str(o.museScorePath) ?? d.museScorePath,
    ffmpegPath: str(o.ffmpegPath) ?? d.ffmpegPath,
    backend: oneOf(o.backend, BACKENDS) ?? d.backend,
    recordingsRetentionDays:
      num(o.recordingsRetentionDays, 0, 3650) ?? d.recordingsRetentionDays,
  };
}

export function loadSettings(): AppSettings {
  try {
    return parseSettings(window.localStorage.getItem(STORAGE_KEY));
  } catch {
    return DEFAULT_SETTINGS;
  }
}

export function saveSettings(settings: AppSettings): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    /* persistence is best-effort — the session keeps working */
  }
}

/** Valid playback-rate options surfaced in 設定 → 再生. */
export function playbackRateOptions(): readonly number[] {
  return RATES;
}

/**
 * React binding: current settings + a merge-style updater that persists
 * immediately (the theme switcher sets the precedent — changes apply at
 * once, no save button).
 */
export function useAppSettings(): {
  settings: AppSettings;
  update: (patch: Partial<AppSettings>) => void;
} {
  const [settings, setSettings] = useState<AppSettings>(loadSettings);
  const update = useCallback((patch: Partial<AppSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      saveSettings(next);
      return next;
    });
  }, []);
  return useMemo(() => ({ settings, update }), [settings, update]);
}
